 306	static int probe_parse_startup_uptime(int argc, char *argv[],
 307	                                      uint64_t *target_ms)
 308	{
 309	  const char *cursor;
 310	  uint32_t value = 0;
 311	
 312	  if (argc == 1)
 313	    {
 314	      *target_ms = MIN_BLE_STARTUP_UPTIME_MS;
 315	      return 0;
 316	    }
 317	
 318	  if (argc == 2 && argv[1][0] != '\0')
 319	    {
 320	      for (cursor = argv[1]; *cursor != '\0'; cursor++)
 321	        {
 322	          if (*cursor < '0' || *cursor > '9')
 323	            {
 324	              goto invalid;
 325	          }
 326	
 327	          value = value * 10u + (uint32_t)(*cursor - '0');
 328	          if (value > 15000u)
 329	            {
 330	              goto invalid;
 331	            }
 332	          }
 333	
 334	      if (value >= 5000u && value <= 15000u && value % 250u == 0)
 335	        {
 336	          *target_ms = value;
 337	          return 0;
 338	        }
 339	    }
 340	
 341	invalid:
 342	  printf("Usage: openvela_ble_probe "
 343	         "[min_uptime_ms: 5000..15000, step 250]\n");
 344	  return -1;
 345	}
