 116	static bool element_id_cmp(void* table, void* id)
 117	{
 118	    uint16_t f_handle = *(uint16_t*)id;
 119	    service_table_t* f_svc_table = (service_table_t*)table;
 120	    return (f_handle >= f_svc_table->start_handle && f_handle <= f_svc_table->end_handle);
 121	}
