 634	static bt_status_t if_gatts_remove_attr_table(void* srv_handle, uint16_t attr_handle)
 635	{
 636	    gatts_service_t* service = srv_handle;
 637	
 638	    CHECK_ENABLED();
 639	    CHECK_SERVICE_VALID(g_gatts_manager.services, service);
 640	
