 201	static void remove_from_server_db(const struct bt_gatt_attr* start, size_t count)
 202	{
 203	    size_t index, i;
 204	
 205	    if (!start || count == 0) {
 206	        return;
 207	    }
 208	
 209	    index = start - server_db;
 210	
 211	    if (start < server_db || index >= attr_count) {
 212	        BT_LOGE("%s, invalid start pointer", __func__);
 213	        return;
 214	    }
 215	
 216	    if (count > attr_count || index + count > attr_count) {
 217	        BT_LOGE("%s, invalid count: %zu (index=%zu, attr_count=%zu)", __func__, count, index, attr_count);
 218	        return;
 219	    }
 220	
 221	    for (i = 0; i < count; i++) {
 222	        free(start[i].user_data);
 223	        free((void*)start[i].uuid);
 224	    }
 225	
 226	    if (index + count < attr_count) {
 227	        memmove(&server_db[index], &server_db[index + count],
 228	            (attr_count - index - count) * sizeof(struct bt_gatt_attr));
 229	    }
 230	
 231	    memset(&server_db[attr_count - count], 0, count * sizeof(struct bt_gatt_attr));
 232	    attr_count -= count;
 233	}
