 887	static struct bt_gatt_attr* get_base_chrc(struct bt_gatt_attr* attr)
 888	{
 889	    struct bt_gatt_attr* tmp;
 890	
 891	    for (tmp = attr; tmp > server_db; tmp--) {
 892	        if (!bt_uuid_cmp(tmp->uuid, BT_UUID_GATT_PRIMARY) || !bt_uuid_cmp(tmp->uuid, BT_UUID_GATT_SECONDARY)) {
 893	            break;
 894	        }
 895	
 896	        if (!bt_uuid_cmp(tmp->uuid, BT_UUID_GATT_CHRC)) {
 897	            return tmp;
 898	        }
 899	    }
 900	
 901	    return NULL;
 902	}
