 904	static void add_descriptor(gatt_element_t* element)
 905	{
 906	    struct add_descriptor desc = { 0 };
 907	    struct bt_gatt_attr* chrc;
 908	    union uuid u;
 909	
 910	    if (!bt_uuid_create(&u.uuid, (uint8_t*)&element->uuid.val, element->uuid.type)) {
 911	        BT_LOGE("%s, uuid convert fail", __func__);
 912	        return;
 913	    }
 914	
 915	    desc.permissions = covert_gatt_permission(element->permissions);
 916	    desc.properties = element->properties;
 917	    desc.uuid = &u.uuid;
 918	    desc.element = element;
 919	
 920	    chrc = get_base_chrc(LAST_DB_ATTR);
 921	    if (!chrc) {
 922	        BT_LOGE("%s, get base chrc fail", __func__);
 923	        return;
 924	    }
 925	
 926	    if (alloc_descriptor(chrc, &desc)) {
 927	        BT_LOGE("%s, alloc descriptor fail", __func__);
 928	        return;
 929	    }
 930	}
