 823	static int alloc_descriptor(const struct bt_gatt_attr* attr, struct add_descriptor* desc)
 824	{
 825	    struct bt_gatt_attr* attr_desc;
 826	    struct gatt_ccc_wrapper* ccc_wrapper;
 827	    struct bt_gatt_chrc* chrc = attr->user_data;
 828	    struct _bt_gatt_ccc* ccc;
 829	    struct gatt_user_data user_data = { 0 };
 830	
 831	    if (bt_uuid_cmp(desc->uuid, BT_UUID_GATT_CCC) == 0) {
 832	
 833	        if (!(chrc->properties & (BT_GATT_CHRC_NOTIFY | BT_GATT_CHRC_INDICATE))) {
 834	            BT_LOGE("%s, invald properties:0x%0x", __func__, chrc->properties);
 835	            return -EINVAL;
 836	        }
 837	
 838	        /* This memory is freed in remove_service() via attr->user_data */
 839	        ccc_wrapper = zalloc(sizeof(struct gatt_ccc_wrapper));
 840	        if (!ccc_wrapper) {
 841	            BT_LOGE("%s, wrapper alloc failed", __func__);
 842	            return -ENOMEM;
 843	        }
 844	
 845	        ccc = &ccc_wrapper->ccc;
 846	        ccc_wrapper->element = desc->element;
 847	
 848	        attr_desc = gatt_db_add(
 849	            &(struct bt_gatt_attr) {
 850	                .uuid = BT_UUID_GATT_CCC,
 851	                .perm = desc->permissions & GATT_PERM_MASK,
 852	                .read = bt_gatt_attr_read_ccc,
 853	                .write = bt_sal_on_ccc_written,
 854	                .user_data = ccc },
 855	            0);
 856	
 857	        if (!attr_desc) {
 858	            free(ccc_wrapper);
 859	            BT_LOGE("%s attr_desc null", __func__);
 860	            return -EINVAL;
 861	        }
 862	
 863	        desc->desc_id = attr_desc->handle;
 864	    } else {
 865	        user_data.element = desc->element;
 866	
 867	        attr_desc = gatt_db_add(
 868	            &(struct bt_gatt_attr)BT_GATT_ATTRIBUTE(
 869	                desc->uuid,
 870	                desc->permissions & GATT_PERM_MASK,
 871	                read_value,
 872	                write_value,
 873	                &user_data),
 874	            sizeof(user_data));
 875	
 876	        if (!attr_desc) {
 877	            BT_LOGE("%s, generic descriptor allocation failed", __func__);
 878	            return -EINVAL;
 879	        }
 880	
 881	        desc->desc_id = attr_desc->handle;
 882	    }
 883	
 884	    return 0;
 885	}
