 587	static void gatt_sdp_delete_record(struct bt_sdp_record* record)
 588	{
 589	    sal_gatt_sdp_record_t* gatt_record;
 590	
 591	    if (!record) {
 592	        BT_LOGE("Invalid SDP record");
 593	        return;
 594	    }
 595	
 596	    for (gatt_record = gatt_sdp_records; gatt_record < gatt_sdp_records + CONFIG_GATT_SERVER_MAX_SERVICES; gatt_record++) {
 597	        if (!gatt_record->srv) {
 598	            continue;
 599	        }
 600	
 601	        if (gatt_record->record == record) {
 602	            gatt_record->srv = NULL;
 603	            gatt_record->record = NULL;
 604	            break;
 605	        }
 606	    }
 607	
 608	    if (record->attrs) {
 609	        gatt_sdp_free_record_attr(record->attrs);
 610	        record->attrs = NULL;
 611	    }
 612	
 613	    free(record);
 614	}
