 616	static bt_status_t register_service(bool is_over_br)
 617	{
 618	    int err;
 619	    int service_index;
 620	    struct bt_sdp_record* record;
 621	    bt_status_t status = BT_STATUS_SUCCESS;
 622	
 623	    service_index = find_free_service_index();
 624	    if (service_index < 0) {
 625	        BT_LOGE("%s, service full", __func__);
 626	        status = BT_STATUS_FAIL;
 627	        goto out;
 628	    }
 629	
 630	    server_svcs[service_index].attrs = server_db + (attr_count - svc_attr_count);
 631	    server_svcs[service_index].attr_count = svc_attr_count;
 632	
 633	    err = bt_gatt_service_register(&server_svcs[service_index]);
 634	    if (err) {
 635	        server_svcs[service_index].attrs = NULL;
 636	        server_svcs[service_index].attr_count = 0;
 637	        BT_LOGD("%s, gatt service register %d", __func__, err);
 638	        status = BT_STATUS_FAIL;
 639	        goto out;
 640	    }
 641	
 642	    if (!is_over_br) {
 643	        goto out;
 644	    }
 645	
 646	    record = gatt_sdp_create_record(&server_svcs[service_index]);
 647	
 648	    if (!record) {
 649	        BT_LOGE("Failed to create SDP record");
 650	        goto out;
 651	    }
 652	
 653	    err = bt_sdp_register_service(record);
 654	    if (err != 0) {
 655	        BT_LOGE("GATT SDP record register fail");
 656	        gatt_sdp_delete_record(record);
 657	        goto out;
 658	    }
 659	
 660	out:
 661	    svc_attr_count = 0U;
 662	    if (status != BT_STATUS_SUCCESS) {
 663	        remove_from_server_db(server_db + (attr_count - svc_attr_count), svc_attr_count);
 664	    }
 665	    return status;
 666	}
