 499	static bt_status_t if_gatts_register_service(void* remote, void** phandle, gatts_callbacks_t* callbacks)
 500	{
 501	    pthread_mutexattr_t attr;
 502	
 503	    CHECK_ENABLED();
 504	    if (!phandle)
 505	        return BT_STATUS_PARM_INVALID;
 506	
 507	    pthread_mutex_lock(&g_gatts_manager.device_lock);
 508	    gatts_service_t* service = gatts_service_new(callbacks);
 509	    if (!service) {
 510	        pthread_mutex_unlock(&g_gatts_manager.device_lock);
 511	        BT_LOGE("New gatts service alloc failed");
 512	        return BT_STATUS_NOMEM;
 513	    }
 514	
 515	    bt_list_add_tail(g_gatts_manager.services, service);
 516	    pthread_mutex_unlock(&g_gatts_manager.device_lock);
 517	
 518	    pthread_mutexattr_init(&attr);
 519	    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
 520	    pthread_mutex_init(&service->srv_lock, &attr);
 521	
 522	    service->remote = remote;
 523	    service->manager = &g_gatts_manager;
 524	    service->user_phandle = phandle;
 525	    *phandle = service;
 526	
 527	    return BT_STATUS_SUCCESS;
 528	}
