1098	bt_status_t bt_sal_gatt_server_add_elements(gatt_element_t* elements, uint16_t size)
1099	{
1100	    size_t index;
1101	    bt_status_t status;
1102	    sal_adapter_req_t* req;
1103	    bool is_over_bredr = false;
1104	
1105	    if (!elements || size == 0)
1106	        return BT_STATUS_PARM_INVALID;
1107	
1108	    for (index = 0; index < size; index++) {
1109	        switch (elements[index].type) {
1110	        case GATT_PRIMARY_SERVICE:
1111	        case GATT_SECONDARY_SERVICE:
1112	            /* Workaround: BR/EDR services to be registered over BLE as well */
1113	            if (elements[index].properties & GATT_PROP_EXPOSED_OVER_BREDR) {
1114	                is_over_bredr = true;
1115	                BT_LOGD("BR/EDR service to be registered over BLE");
1116	            }
1117	            add_service(&elements[index], is_over_bredr);
1118	            break;
1119	        case GATT_CHARACTERISTIC:
1120	            add_characteristic(&elements[index]);
1121	            break;
1122	        case GATT_DESCRIPTOR:
1123	            add_descriptor(&elements[index]);
1124	            break;
1125	        default:
1126	            BT_LOGE("%s, unsupported type: %d", __func__, elements[index].type);
1127	            break;
1128	        }
1129	    }
1130	
1131	    req = calloc(1, sizeof(sal_adapter_req_t));
1132	    if (!req)
1133	        return BT_STATUS_NOMEM;
1134	
1135	    status = register_service(is_over_bredr);
1136	    if (status != BT_STATUS_SUCCESS) {
1137	        free(req);
1138	        return status;
1139	    }
1140	
1141	    req->func = sal_gatts_elements_callback;
1142	    req->adpt.attr_op.element_id = elements[0].handle;
1143	    req->adpt.attr_op.size = size;
1144	    req->adpt.attr_op.type = GATTS_CB_TYPE_ADDED;
1145	
1146	    return sal_send_req((void*)req);
1147	}
