1149	static sal_gatt_sdp_record_t* get_sdp_from_service(struct bt_gatt_service* srv)
1150	{
1015		 * However Vol 3, Part F, 3.3.1 says that multi-octet Characteristic
1016		 * Values shall be LE unless otherwise defined. PTS expects hash to be
1017		 * in little endianness as well. bt_smp_aes_cmac calculates the hash in
1018		 * big endianness so we have to swap.
1019		 */
1020		sys_mem_swap(hdev->gatt_ctx->db_hash.hash, sizeof(hdev->gatt_ctx->db_hash.hash));
1021	
1022		LOG_HEXDUMP_DBG(hdev->gatt_ctx->db_hash.hash, sizeof(hdev->gatt_ctx->db_hash.hash), "Hash: ");
1023	
1024		atomic_set_bit(hdev->gatt_ctx->gatt_sc.flags, DB_HASH_VALID);
1025	}
1026	
1027	static void sc_indicate(struct bt_dev *hdev, uint16_t start, uint16_t end);
1028	
1029	static void do_db_hash(struct bt_dev* hdev)
1030	{
1031		bool new_hash = !atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, DB_HASH_VALID);
1032	
1033		if (new_hash) {
1034			db_hash_gen();
1035		}
1036	
1037	#if defined(CONFIG_BT_SETTINGS)
1038		bool hash_loaded_from_settings =
1039			atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, DB_HASH_LOAD);
1040		bool already_processed =
1041			atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, DB_HASH_LOAD_PROC);
1042	
1043		if (!hash_loaded_from_settings) {
1044			/* we want to generate the hash, but not overwrite the hash
1045			 * stored in settings, that we haven't yet loaded.
1046			 */
1047			return;
1048		}
1049	
1050		if (already_processed) {
1051			/* hash has been loaded from settings and we have already
1052			 * executed the special case below once. we can now safely save
1053			 * the calculated hash to settings (if it has changed).
1054			 */
1055			if (new_hash) {
1056				set_all_change_unaware();
1057				db_hash_store();
1058			}
1059		} else {
1060			/* this is only supposed to run once, on bootup, after the hash
1061			 * has been loaded from settings.
1062			 */
1063			atomic_set_bit(hdev->gatt_ctx->gatt_sc.flags, DB_HASH_LOAD_PROC);
1064	
1065			/* Check if hash matches then skip SC update */
1066			if (!memcmp(hdev->gatt_ctx->db_hash.stored_hash, hdev->gatt_ctx->db_hash.hash,
1067				    sizeof(hdev->gatt_ctx->db_hash.stored_hash))) {
1068				LOG_DBG("Database Hash matches");
1069				k_work_cancel_delayable(&hdev->gatt_ctx->gatt_sc.work);
1070				atomic_clear_bit(hdev->gatt_ctx->gatt_sc.flags, SC_RANGE_CHANGED);
1071				return;
1072			}
1073	
1074			LOG_HEXDUMP_DBG(hdev->gatt_ctx->db_hash.hash, sizeof(hdev->gatt_ctx->db_hash.hash), "New Hash: ");
1075	
1076			/* GATT database has been modified since last boot, likely due
1077			 * to a firmware update or a dynamic service that was not
1078			 * re-registered on boot.
1079			 * Indicate Service Changed to all bonded devices for the full
1080			 * database range to invalidate client-side cache and force
1081			 * discovery on reconnect.
1082			 */
1083			sc_indicate(0x0001, 0xffff);
1084	
1085			/* Hash did not match, overwrite with current hash.
1086			 * Also immediately set all peers (in settings) as
1087			 * change-unaware.
1088			 */
1089			set_all_change_unaware();
1090			db_hash_store();
1091		}
1092	#endif /* defined(CONFIG_BT_SETTINGS) */
1093	}
1094	
1095	static void db_hash_process(struct k_work *work)
1096	{
1097		struct db_hash *hash = CONTAINER_OF(work, struct db_hash, work);
1098		struct bt_dev_gatt_ctx *gatt_ctx = CONTAINER_OF(hash, struct bt_dev_gatt_ctx, db_hash);
1099	
1100		do_db_hash(gatt_ctx->hdev);
1101	}
