1443		/* BLUETOOTH CORE SPECIFICATION Version 5.3 | Vol 3, Part G page 1476:
1444		 * 2.5.2.1 Robust Caching
1445		 * ... a change-unaware connected client using exactly one ATT bearer
1446		 * becomes change-aware when ...
1447		 * The client receives and confirms a Handle Value Indication
1448		 * for the Service Changed characteristic
1449		 */
1450		if (bt_att_fixed_chan_only(conn)) {
1451			cfg = find_cf_cfg(conn);
