1089	static uint8_t find_info_cb(const struct bt_gatt_attr *attr, uint16_t handle,
1090				    void *user_data)
1091	{
1092		struct find_info_data *data = user_data;
1093		struct bt_att_chan *chan = data->chan;
1094	
1095		LOG_DBG("handle 0x%04x", handle);
1096	
1097		/* Initialize rsp at first entry */
1098		if (!data->rsp) {
1099			data->rsp = net_buf_add(data->buf, sizeof(*data->rsp));
1100			data->rsp->format = (attr->uuid->type == BT_UUID_TYPE_16) ?
1101					    BT_ATT_INFO_16 : BT_ATT_INFO_128;
1102		}
1103	
1104		switch (data->rsp->format) {
1105		case BT_ATT_INFO_16:
1106			if (attr->uuid->type != BT_UUID_TYPE_16) {
1107				return BT_GATT_ITER_STOP;
1108			}
1109	
1110			/* Fast forward to next item position */
1111			data->info16 = net_buf_add(data->buf, sizeof(*data->info16));
1112			data->info16->handle = sys_cpu_to_le16(handle);
1113			data->info16->uuid = sys_cpu_to_le16(BT_UUID_16(attr->uuid)->val);
1114	
1115			if (bt_att_mtu(chan) - data->buf->len >
1116			    sizeof(*data->info16)) {
1117				return BT_GATT_ITER_CONTINUE;
1118			}
1119	
1120			break;
1121		case BT_ATT_INFO_128:
1122			if (attr->uuid->type != BT_UUID_TYPE_128) {
1123				return BT_GATT_ITER_STOP;
1124			}
1125	
1126			/* Fast forward to next item position */
1127			data->info128 = net_buf_add(data->buf, sizeof(*data->info128));
1128			data->info128->handle = sys_cpu_to_le16(handle);
1129			memcpy(data->info128->uuid, BT_UUID_128(attr->uuid)->val,
1130			       sizeof(data->info128->uuid));
1131	
1132			if (bt_att_mtu(chan) - data->buf->len >
1133			    sizeof(*data->info128)) {
1134				return BT_GATT_ITER_CONTINUE;
1135			}
1136		}
1137	
1138		return BT_GATT_ITER_STOP;
1139	}
