1145		struct bt_dev *hdev = chan->att->conn->hdev;
1146	
1147		(void)memset(&data, 0, sizeof(data));
1148	
1149		data.buf = bt_att_create_rsp_pdu(chan, BT_ATT_OP_FIND_INFO_RSP);
1150		if (!data.buf) {
1151			return BT_ATT_ERR_INSUFFICIENT_RESOURCES;
1152		}
1153	
1154		data.chan = chan;
