2062	static uint8_t att_read_group_req(struct bt_att_chan *chan, struct net_buf *buf)
2063	{
2064		struct bt_att_read_group_req *req;
2065		uint16_t start_handle, end_handle, err_handle;
2066		union {
2067			struct bt_uuid uuid;
2068			struct bt_uuid_16 u16;
2069			struct bt_uuid_128 u128;
2070		} u;
2071		uint8_t uuid_len = buf->len - sizeof(*req);
2072	
2073		/* Type can only be UUID16 or UUID128 */
2074		if (uuid_len != 2 && uuid_len != 16) {
2075			return BT_ATT_ERR_INVALID_PDU;
2076		}
2077	
2078		req = net_buf_pull_mem(buf, sizeof(*req));
2079	
2080		start_handle = sys_le16_to_cpu(req->start_handle);
2081		end_handle = sys_le16_to_cpu(req->end_handle);
2082	
2083		if (!bt_uuid_create(&u.uuid, req->uuid, uuid_len)) {
2084			return BT_ATT_ERR_UNLIKELY;
2085		}
2086	
2087		LOG_DBG("start_handle 0x%04x end_handle 0x%04x type %s", start_handle, end_handle,
2088			bt_uuid_str(&u.uuid));
2089	
2090		if (!range_is_valid(start_handle, end_handle, &err_handle)) {
2091			send_err_rsp(chan, BT_ATT_OP_READ_GROUP_REQ, err_handle,
2092				     BT_ATT_ERR_INVALID_HANDLE);
2093			return 0;
2094		}
2095	
2096		/* Core v4.2, Vol 3, sec 2.5.3 Attribute Grouping:
2097		 * Not all of the grouping attributes can be used in the ATT
2098		 * Read By Group Type Request. The "Primary Service" and "Secondary
2099		 * Service" grouping types may be used in the Read By Group Type
2100		 * Request. The "Characteristic" grouping type shall not be used in
2101		 * the ATT Read By Group Type Request.
2102		 */
2103		if (bt_uuid_cmp(&u.uuid, BT_UUID_GATT_PRIMARY) &&
2104		    bt_uuid_cmp(&u.uuid, BT_UUID_GATT_SECONDARY)) {
2105			send_err_rsp(chan, BT_ATT_OP_READ_GROUP_REQ, start_handle,
2106				     BT_ATT_ERR_UNSUPPORTED_GROUP_TYPE);
2107			return 0;
2108		}
2109	
2110		return att_read_group_rsp(chan, &u.uuid, start_handle, end_handle);
2111	}
