  1079	struct find_info_data {
  1080		struct bt_att_chan *chan;
  1081		struct net_buf *buf;
  1082		struct bt_att_find_info_rsp *rsp;
  1083		union {
  1084			struct bt_att_info_16 *info16;
  1085			struct bt_att_info_128 *info128;
  1086		};
