  1141	static uint8_t att_find_info_rsp(struct bt_att_chan *chan, uint16_t start_handle,
  1142				      uint16_t end_handle)
  1143	{
  1144		struct find_info_data data;
  1145		struct bt_dev *hdev = chan->att->conn->hdev;
  1146	
  1147		(void)memset(&data, 0, sizeof(data));
  1148	
  1149		data.buf = bt_att_create_rsp_pdu(chan, BT_ATT_OP_FIND_INFO_RSP);
  1150		if (!data.buf) {
  1151			return BT_ATT_ERR_INSUFFICIENT_RESOURCES;
  1152		}
  1153	
  1154		data.chan = chan;
  1155		bt_gatt_foreach_attr_mc(hdev->dev_id, start_handle, end_handle, find_info_cb, &data);
  1156	
  1157		if (!data.rsp) {
  1158			net_buf_unref(data.buf);
  1159			/* Respond since handle is set */
  1160			send_err_rsp(chan, BT_ATT_OP_FIND_INFO_REQ, start_handle,
  1161				     BT_ATT_ERR_ATTRIBUTE_NOT_FOUND);
  1162			return 0;
  1163		}
  1164	
  1165		bt_att_chan_send_rsp(chan, data.buf);
  1166	
  1167		return 0;
  1168	}
