  1603	static uint8_t att_read_type_req(struct bt_att_chan *chan, struct net_buf *buf)
  1604	{
  1605		struct bt_att_read_type_req *req;
  1606		uint16_t start_handle, end_handle, err_handle;
  1607		union {
  1608			struct bt_uuid uuid;
  1609			struct bt_uuid_16 u16;
  1610			struct bt_uuid_128 u128;
  1611		} u;
  1612		uint8_t uuid_len = buf->len - sizeof(*req);
  1613	
  1614		/* Type can only be UUID16 or UUID128 */
  1615		if (uuid_len != 2 && uuid_len != 16) {
  1616			return BT_ATT_ERR_INVALID_PDU;
  1617		}
  1618	
  1619		req = net_buf_pull_mem(buf, sizeof(*req));
  1620	
  1621		start_handle = sys_le16_to_cpu(req->start_handle);
  1622		end_handle = sys_le16_to_cpu(req->end_handle);
  1623		if (!bt_uuid_create(&u.uuid, req->uuid, uuid_len)) {
  1624			return BT_ATT_ERR_UNLIKELY;
  1625		}
  1626	
  1627		LOG_DBG("start_handle 0x%04x end_handle 0x%04x type %s", start_handle, end_handle,
  1628			bt_uuid_str(&u.uuid));
  1629	
  1630		if (!range_is_valid(start_handle, end_handle, &err_handle)) {
  1631			send_err_rsp(chan, BT_ATT_OP_READ_TYPE_REQ, err_handle,
  1632				     BT_ATT_ERR_INVALID_HANDLE);
  1633			return 0;
  1634		}
  1635	
  1636		/* Reading Database Hash is special as it may be used to make client change aware
  1637		 * (Core Specification 5.4 Vol 3. Part G. 2.5.2.1 Robust Caching).
  1638		 *
  1639		 * GATT client shall always use GATT Read Using Characteristic UUID sub-procedure for
  1640		 * reading Database Hash
  1641		 * (Core Specification 5.4 Vol 3. Part G. 7.3 Databse Hash)
  1642		 */
  1643		if (bt_uuid_cmp(&u.uuid, BT_UUID_GATT_DB_HASH) != 0) {
  1644			if (!bt_gatt_change_aware(chan->att->conn, true)) {
  1645				if (!atomic_test_and_set_bit(chan->flags, ATT_OUT_OF_SYNC_SENT)) {
  1646					return BT_ATT_ERR_DB_OUT_OF_SYNC;
  1647				} else {
  1648					return 0;
  1649				}
  1650			}
  1651		}
  1652	
  1653		return att_read_type_rsp(chan, &u.uuid, start_handle, end_handle);
  1654	}
