  1459	static void sc_process(struct k_work *work)
  1460	{
  1461		struct k_work_delayable *dwork = k_work_delayable_from_work(work);
  1462		struct gatt_sc *sc = CONTAINER_OF(dwork, struct gatt_sc, work);
  1463		uint16_t sc_range[2];
  1464	
  1465		__ASSERT(!atomic_test_bit(sc->flags, SC_INDICATE_PENDING),
  1466			 "Indicate already pending");
  1467	
  1468		LOG_DBG("start 0x%04x end 0x%04x", sc->start, sc->end);
  1469	
  1470		sc_range[0] = sys_cpu_to_le16(sc->start);
  1471		sc_range[1] = sys_cpu_to_le16(sc->end);
  1472	
  1473		atomic_clear_bit(sc->flags, SC_RANGE_CHANGED);
  1474		sc->start = 0U;
  1475		sc->end = 0U;
  1476	
  1477		sc->params.attr = &_1_gatt_svc.attrs[2];
  1478		sc->params.func = sc_indicate_rsp;
  1479		sc->params.data = &sc_range[0];
  1480		sc->params.len = sizeof(sc_range);
  1481	#if defined(CONFIG_BT_EATT)
  1482		sc->params.chan_opt = BT_ATT_CHAN_OPT_NONE;
  1483	#endif /* CONFIG_BT_EATT */
  1484	
  1485		if (bt_gatt_indicate(NULL, &sc->params)) {
  1486			/* No connections to indicate */
  1487			return;
  1488		}
  1489	
  1490		atomic_set_bit(sc->flags, SC_INDICATE_PENDING);
  1491	}
