    62	static void board_init_psram(void)
    63	{
    64	    qspi_configure_t qspi_cfg =
    65	    {
    66	        .Instance = hwp_qspi1,
    67	        .SpiMode = BSP_QSPI1_MODE,
    68	        .msize = BSP_QSPI1_MEM_SIZE,
    69	        .base = QSPI1_MEM_BASE,
    70	    };
    71	    uint32_t pid = (hwp_hpsys_cfg->IDR & HPSYS_CFG_IDR_PID_Msk) >> HPSYS_CFG_IDR_PID_Pos;
    72	    pid &= 7;
    73	
    74	    switch (pid)
    75	    {
    76	    case 5: //BOOT_PSRAM_APS_16P:
    77	        qspi_cfg.SpiMode = SPI_MODE_PSRAM;         // 16Mb APM QSPI PSRAM
    78	        break;
    79	    case 4: //BOOT_PSRAM_APS_32P:
    80	        qspi_cfg.SpiMode = SPI_MODE_LEGPSRAM;    // 32Mb APM LEGACY PSRAM
    81	        break;
    82	    case 6: //BOOT_PSRAM_WINBOND:                // Winbond HYPERBUS PSRAM
    83	        qspi_cfg.SpiMode = SPI_MODE_HBPSRAM;
    84	        break;
    85	    case 3: // BOOT_PSRAM_APS_64P:
    86	    case 2: //BOOT_PSRAM_APS_128P:
    87	        qspi_cfg.SpiMode = SPI_MODE_OPSRAM;      // 64Mb APM XCELLA PSRAM
    88	        break;
    89	    default:
    90	        qspi_cfg.SpiMode = SPI_MODE_NOR;
    91	        break;
    92	    }
    93	    static FLASH_HandleTypeDef f_handle;
    94	    if (PM_STANDBY_BOOT != SystemPowerOnModeGet())
    95	        f_handle.wakeup = 0;
    96	    else
    97	        f_handle.wakeup = 1;
    98	    HAL_MPI_PSRAM_Init(&f_handle, &qspi_cfg, mpi1_div);
    99	}
   100	#endif
