	struct k_work_delayable *dwork = k_work_delayable_from_work(work);
	struct bt_att_chan *chan = CONTAINER_OF(dwork, struct bt_att_chan,
						timeout_work);
	struct bt_conn *conn = chan->att->conn;
	int err;

	if (!conn) {
		LOG_ERR("conn is null");
		return;
	}

	if (conn->type == BT_CONN_TYPE_LE) {
		bt_addr_le_to_str(bt_conn_get_dst(conn), addr, sizeof(addr));
	} else if (conn->type == BT_CONN_TYPE_BR) {
		bt_addr_to_str(bt_conn_get_dst_br(conn), addr, sizeof(addr));
	}

	LOG_ERR("ATT Timeout for device %s. Disconnecting...", addr);

	if (IS_ENABLED(CONFIG_BT_ATT_OVER_BR) && bt_att_is_over_br(chan)) {
		/* timeout execute att_br disconnect
		 *
		 * bt_att_disconnected will be called after L2CAP disconnected, so
		 * not call it again here.
		 */
		err = bt_l2cap_chan_disconnect(&chan->br_chan.chan);
		if (err) {
			LOG_ERR("Disconnecting failed (err %d)", err);
		}
		return;
	}

	/* BLUETOOTH SPECIFICATION Version 4.2 [Vol 3, Part F] page 480:
	 *
	 * A transaction not completed within 30 seconds shall time out. Such a
	 * transaction shall be considered to have failed and the local higher
	 * layers shall be informed of this failure. No more attribute protocol
	 * requests, commands, indications or notifications shall be sent to the
	 * target device on this ATT Bearer.
