			if (callback->connected) {
				callback->connected(chan->conn);
			}
		}
	} else {
		le_chan = BT_L2CAP_LE_CHAN(chan);
		conn = le_chan->chan.conn;
		LOG_DBG("chan %p cid 0x%04x", le_chan, le_chan->tx.cid);
